"""fit.py: crdist-poly.h, the polynomials of crdist's fast path (crdist-fast.h), from mpmath. Run from dist/:
    python3 fit.py > crdist-poly.h
Each polynomial interpolates its function at the Chebyshev nodes of its interval, in 60 digits, and its
coefficients are then rounded to binary64; the script prints, to stderr, the largest relative error on a grid of
2,001 points, of the exact polynomial and of the rounded one evaluated by Horner's rule in binary64. Those are
design figures: the bound crdist relies on is checked against MPFR on every input (crdist-check bound-all).

- erfinv(x) = x P(x^2) for 0 <= x <= 1/2: P of degree 13 in z = x^2 on [0, 1/4].
- erfcinv(q) for 0 < q <= 1/2, as a function of s = sqrt(-log q), 0.8326 <= s <= 10.17 (q down to 2^-149):
  six pieces of s, each a polynomial of degree 14 in s - m, m the piece's middle.
Written 2026-10-12."""
import sys
import mpmath as mp

mp.mp.dps = 60
PIECES = [(None, '1.3'), ('1.3', '2'), ('2', '3'), ('3', '4.5'), ('4.5', '6.5'), ('6.5', '10.2')]
DEG_C, DEG_T = 13, 14


def g_center(z):
    if z == 0:
        return mp.sqrt(mp.pi) / 2
    x = mp.sqrt(z)
    return mp.erfinv(x) / x


def y_tail(s):
    """erfcinv(exp(-s^2)): Newton on log erfc(t) + s^2 = 0"""
    t = s - mp.log(s * mp.sqrt(mp.pi)) / (2 * s) if s > 1 else mp.erfinv(1 - mp.exp(-s * s))
    for _ in range(100):
        e = mp.erfc(t)
        t2 = t - (mp.log(e) + s * s) / (-2 * mp.exp(-t * t) / (mp.sqrt(mp.pi) * e))
        if abs(t2 - t) < mp.mpf(10) ** -55 * abs(t):
            return t2
        t = t2
    raise ValueError(s)


def interpolate(f, a, b, n, m):
    """monomial coefficients in (t - m) of the interpolant of f at n + 1 Chebyshev nodes of [a, b]"""
    nodes = [(a + b) / 2 + (b - a) / 2 * mp.cos(mp.pi * (k + mp.mpf(1) / 2) / (n + 1)) for k in range(n + 1)]
    A = mp.matrix([[(t - m) ** j for j in range(n + 1)] for t in nodes])
    c = mp.lu_solve(A, mp.matrix([f(t) for t in nodes]))
    return [c[j] for j in range(n + 1)]


def horner(cd, d):
    h = cd[-1]
    for c in reversed(cd[:-1]):
        h = h * d + c
    return h


def errors(f, a, b, c, m):
    cd, md = [float(x) for x in c], float(m)
    wa = wd = mp.mpf(0)
    for i in range(2001):
        t = mp.mpf(float(a + (b - a) * i / 2000))
        ex = f(t)
        wa = max(wa, abs(sum(c[j] * (t - m) ** j for j in range(len(c))) / ex - 1))
        wd = max(wd, abs(mp.mpf(horner(cd, float(t) - md)) / ex - 1))
    return float(mp.log(wa, 2)), float(mp.log(wd, 2))


def hexs(v):
    return float(v).hex()


out = ['/* crdist-poly.h: generated by dist/fit.py (python3 fit.py > crdist-poly.h); do not edit.',
       '   The polynomials of crdist-fast.h, interpolated at Chebyshev nodes in 60 digits (mpmath) and rounded. */']
c = interpolate(g_center, mp.mpf(0), mp.mpf('0.25'), DEG_C, mp.mpf(0))
ea, ed = errors(g_center, mp.mpf(0), mp.mpf('0.25'), c, mp.mpf(0))
print(f"center, degree {DEG_C}: interpolant 2^{ea:.1f}, rounded and in binary64 2^{ed:.1f}", file=sys.stderr)
out.append(f'/* erfinv(x) = x P(x^2), 0 <= x <= 1/2: P(z) = sum C[j] z^j */')
out.append(f'#define CRDIST_DEG_C {DEG_C}')
out.append('static const double crdist_c[CRDIST_DEG_C + 1] = {\n  ' +
           ',\n  '.join(', '.join(hexs(x) for x in c[i:i + 4]) for i in range(0, len(c), 4)) + '};')
lo = mp.sqrt(mp.log(2))
out.append(f'/* erfcinv(q), 0 < q <= 1/2, s = sqrt(-log q): piece k for s below crdist_t_end[k], the polynomial in s - m_k */')
out.append(f'#define CRDIST_NPIECE {len(PIECES)}')
out.append(f'#define CRDIST_DEG_T {DEG_T}')
ends, mids, rows = [], [], []
for a, b in PIECES:
    a = lo if a is None else mp.mpf(a)
    b = mp.mpf(b)
    m = mp.mpf(float((a + b) / 2))   # the middle, as a binary64 number, so that s - m is exact (Sterbenz)
    c = interpolate(y_tail, a, b, DEG_T, m)
    ea, ed = errors(y_tail, a, b, c, m)
    print(f"tail [{float(a):.4f}, {float(b)}], degree {DEG_T}: interpolant 2^{ea:.1f}, rounded and in binary64 2^{ed:.1f}",
          file=sys.stderr)
    ends.append(hexs(b))
    mids.append(hexs(m))
    rows.append('  {' + ',\n   '.join(', '.join(hexs(x) for x in c[i:i + 4]) for i in range(0, len(c), 4)) + '}')
out.append('static const double crdist_t_end[CRDIST_NPIECE] = {' + ', '.join(ends) + '};')
out.append('static const double crdist_t_mid[CRDIST_NPIECE] = {' + ', '.join(mids) + '};')
out.append('static const double crdist_t[CRDIST_NPIECE][CRDIST_DEG_T + 1] = {\n' + ',\n'.join(rows) + '};')
print('\n'.join(out))
